def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast counters
    opp_d = 0
    opp_c = 0
    my_d = 0
    for me, op in history:
        if op == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if me == 'D':
            my_d += 1

    last_me, last_op = history[-1]
    remaining = 100 - n

    # Immediate endgame exploitation
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        if opp_d >= n - 1:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Pure cooperator detection: keep mutual CC, harvest last round
    if opp_d == 0:
        if remaining <= 1:
            return 'D'
        return 'C'

    # Pure defector: defect, rare probe when very late for possible reset
    if opp_c == 0:
        if remaining < 12 and rng.random() < 0.1:
            return 'C'
        return 'D'

    # Recent opponent behavior
    look = 12 if n >= 12 else n
    recent_opp_d = 0
    for i in range(n - look, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
    recent_rate = (look - recent_opp_d) / float(look)

    # Long-term rates for context
    total_rate = opp_c / float(n)

    # Opponent is heavily defecting: punish hard, with small probing
    if recent_opp_d >= look - 2:
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    if recent_rate < 0.25:
        if last_op == 'D':
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if recent_rate < 0.5:
        if last_op == 'D':
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        if my_d > opp_d + 3:
            return 'C'
        return 'C'

    # Opponent moderately-to-highly cooperative
    if total_rate > 0.9 and recent_rate > 0.85:
        if remaining <= 1:
            return 'D'
        # occasional probe to grab a higher payoff without destroying trust
        if n >= 10 and n % 11 == 0:
            return 'D'
        return 'C'

    if last_op == 'D':
        # Forgive a single recent defection if opponent was otherwise good
        recent_defs5 = 0
        lo = n - 5 if n >= 5 else 0
        for i in range(lo, n):
            if history[i][1] == 'D':
                recent_defs5 += 1
        if recent_defs5 == 1 and total_rate > 0.7:
            if rng.random() < 0.5:
                return 'C'
        if remaining <= 5 and total_rate > 0.75:
            return 'C'
        return 'D'

    if my_d > opp_d + 2 and total_rate < 0.6:
        return 'D'

    return 'C'
